using SagreEventi.Shared.Models;

namespace SagreEventi.Web.Server.Models.Entities;

/// <summary>
/// Row of the <c>StatiModerazione</c> lookup table: it only documents, inside the database, the numeric values of
/// <see cref="StatoModerazione"/> and lets <c>Eventi.Stato</c> be a foreign key. The enum stays the source of truth:
/// the rows are seeded from it, and a new enum value needs a new migration.
/// </summary>
public class StatoModerazioneLookup
{
    /// <summary>Numeric value of the enum, also the primary key (never generated by the database).</summary>
    public StatoModerazione Id { get; set; }

    /// <summary>Name of the enum member, e.g. <c>InAttesa</c>.</summary>
    public string Nome { get; set; } = string.Empty;
}
